import { useEffect, useId, useRef, useState } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  title: string;
  code: string;
  onCopy: (code: string) => void;
}

type CopyStatus = "idle" | "copied" | "failed";

const STATUS_RESET_MS = 2000;

export function CodeCard({ title, code, onCopy }: CodeCardProps) {
  const [status, setStatus] = useState<CopyStatus>("idle");
  const titleId = useId();
  const statusTimer = useRef<number | undefined>(undefined);

  useEffect(() => {
    return () => window.clearTimeout(statusTimer.current);
  }, []);

  const showStatus = (next: CopyStatus) => {
    setStatus(next);
    window.clearTimeout(statusTimer.current);
    statusTimer.current = window.setTimeout(() => setStatus("idle"), STATUS_RESET_MS);
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      onCopy(code);
      showStatus("copied");
    } catch {
      showStatus("failed");
    }
  };

  const statusText =
    status === "copied" ? "Copied to clipboard" : status === "failed" ? "Copy failed" : "";

  return (
    <section className="codecard" aria-labelledby={titleId}>
      <header className="codecard__header">
        <h3 className="codecard__title" id={titleId}>
          {title}
        </h3>
        <button
          type="button"
          className="codecard__button"
          onClick={handleCopy}
        >
          Copy
        </button>
      </header>

      <pre className="codecard__code" tabIndex={0} aria-labelledby={titleId}>
        <code>{code}</code>
      </pre>

      <p className="codecard__status" role="status" aria-live="polite">
        {statusText}
      </p>
    </section>
  );
}
