    --codecard-accent-fg: #10231b;
    --codecard-focus: #8ab4ff;
    --codecard-button-hover: #96c8b1;
  }
}

.codecard__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.codecard__title {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--codecard-title);
}

.codecard__button {
  flex: none;
  padding: 0.4rem 0.9rem;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--codecard-accent);
  color: var(--codecard-accent-fg);
  font: inherit;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 150ms ease;
}

.codecard__button:hover {
  background: var(--codecard-button-hover);
}

.codecard__button:active {
  transform: translateY(1px);
}

.codecard__code {
  margin: 0;
  padding: 0.75rem 0.9rem;
  overflow-x: auto;
  border-radius: 8px;
  background: var(--codecard-code-bg);
  color: var(--codecard-code-fg);
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 0.85rem;
  line-height: 1.55;
  tab-size: 2;
  white-space: pre;
}

.codecard__code code {
  font: inherit;
}

.codecard__status {
  margin: 0;
  min-height: 1.2em;
  font-size: 0.8rem;
  color: var(--codecard-muted);
}

/* Keyboard focus: visible on both the button and the scrollable code block. */
.codecard__button:focus-visible,
.codecard__code:focus-visible {
  outline: 2px solid var(--codecard-focus);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .codecard__button {
    transition: none;
  }

  .codecard__button:active {
    transform: none;
  }
}
